#include "ships/ShipyardDesignDnaSystem.h"
#include <algorithm>
#include <unordered_map>
namespace subspace {ShipyardDesignDna ShipyardDesignDnaSystem::Extract(const ShipyardModuleRecord&r){ShipyardDesignDna d;d.id=r.source.moduleId;float w=r.source.halfWidth*2,l=r.source.halfLength*2,h=r.source.halfHeight*2,m=std::max({.001f,w,l,h});d.widthRatio=w/m;d.lengthRatio=l/m;d.heightRatio=h/m;d.bilateralSymmetry=r.pairedPlacement||r.mirrorPreferred||r.semantic==ShipyardModuleSemantic::Wing;d.socketCount=static_cast<int>(r.sockets.size());d.detailDensity=std::min(1.f,(static_cast<float>(r.sockets.size())+.5f*(r.surfaceOnly?1:0))/6.f);d.allowedOperators={"uniform_scale"};if(r.preserveAspectRatio)d.allowedOperators.push_back("repeat_safe_sections");if(d.bilateralSymmetry)d.allowedOperators.push_back("mirror_x");if(r.semantic==ShipyardModuleSemantic::HullMid||r.semantic==ShipyardModuleSemantic::EngineHousing)d.allowedOperators.push_back("axial_stretch");d.styleTags={ShipyardModuleSystem::ClassName(r.moduleClass),ShipyardModuleSystem::SemanticName(r.semantic),ShipyardModuleSystem::SizeName(r.size)};return d;}ShipyardDesignExemplar ShipyardDesignDnaSystem::BuildExemplar(const std::string&id,const std::string&role,const std::vector<ShipyardModuleRecord>&c,const ProceduralShipVisualRecipe&r){ShipyardDesignExemplar e;e.id=id;e.role=role.empty()?r.role:role;if(r.modules.empty())return e;int bi=0,af=0,cmd=0;float minY=1e9f,maxY=-1e9f,cy=0;for(const auto&p:r.modules){const ShipyardModuleRecord*x=nullptr;for(const auto&q:c)if(q.source.moduleId==p.moduleId){x=&q;break;}if(!x)continue;e.modules.push_back(Extract(*x));if(x->pairedPlacement||x->mirrorPreferred||x->semantic==ShipyardModuleSemantic::Wing)++bi;if(x->semantic==ShipyardModuleSemantic::MainEngine||x->semantic==ShipyardModuleSemantic::EngineHousing)++af;if(x->moduleClass==ShipyardModuleClass::Command){cy+=p.y;++cmd;}minY=std::min(minY,p.y);maxY=std::max(maxY,p.y);}float n=static_cast<float>(std::max<std::size_t>(1,e.modules.size()));e.symmetryRatio=bi/n;e.aftPropulsionRatio=af/n;if(cmd&&maxY>minY)e.commandForwardBias=((cy/cmd)-minY)/(maxY-minY);return e;}ShipyardDesignGrammar ShipyardDesignDnaSystem::BuildGrammar(const std::string&id,const std::vector<ShipyardDesignExemplar>&es){ShipyardDesignGrammar g;g.id=id;g.exemplarCount=static_cast<int>(es.size());if(es.empty())return g;g.role=es.front().role;std::unordered_map<std::string,int>count;for(const auto&e:es){g.symmetryWeight+=e.symmetryRatio;g.propulsionAftWeight+=e.aftPropulsionRatio;g.commandForwardWeight+=e.commandForwardBias;for(const auto&d:e.modules)for(const auto&t:d.styleTags)count[t]++;}float inv=1.f/es.size();g.symmetryWeight*=inv;g.propulsionAftWeight*=inv;g.commandForwardWeight*=inv;std::vector<std::pair<std::string,int>>rank(count.begin(),count.end());std::sort(rank.begin(),rank.end(),[](const auto&a,const auto&b){return a.second>b.second;});for(std::size_t i=0;i<std::min<std::size_t>(8,rank.size());++i)g.preferredSemantics.push_back(rank[i].first);return g;}}
